{
  "name": "medieval-kingdom-dashboard",
  "version": "1.0.0",
  "scripts": {
    "dev": "node server/index.js",
    "build": "cd client && npm install && npm run build",
    "start": "node server/index.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "express-session": "^1.17.3",
    "passport": "^0.7.0",
    "passport-discord": "^0.1.4",
    "cors": "^2.8.5",
    "dotenv": "^16.3.1"
  }
}

require('dotenv').config({ path: '../MedievalKingdom/MedievalKingdom/.env' });

const express = require('express');
const session = require('express-session');
const passport = require('passport');
const DiscordStrategy = require('passport-discord').Strategy;
const cors = require('cors');
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = process.env.DASHBOARD_PORT || 5000;

const DB_PATH = path.join(__dirname, '../../MedievalKingdom/MedievalKingdom/database');
const ITEMS_PATH = path.join(DB_PATH, 'items.json');
const QUESTS_PATH = path.join(DB_PATH, 'quests.json');
const FAMILIARS_PATH = path.join(DB_PATH, 'familiars.json');
const PLAYERS_PATH = path.join(DB_PATH, 'players.json');

const { classes, factions, monsters } = require('../../MedievalKingdom/MedievalKingdom/systems/gameData.js');

function loadJSON(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch {
    return null;
  }
}

function loadPlayers() {
  return loadJSON(PLAYERS_PATH) || {};
}

const DISCORD_CLIENT_ID = process.env.CLIENT_ID || process.env.DISCORD_CLIENT_ID || '';
const DISCORD_CLIENT_SECRET = process.env.DISCORD_CLIENT_SECRET || '';
const SESSION_SECRET = process.env.SESSION_SECRET || 'medieval-kingdom-secret-2024';
const BASE_URL = process.env.BASE_URL || `https://${process.env.REPLIT_DEV_DOMAIN || `localhost:${PORT}`}`;

const useDiscordAuth = DISCORD_CLIENT_ID && DISCORD_CLIENT_SECRET;

if (useDiscordAuth) {
  passport.use(new DiscordStrategy({
    clientID: DISCORD_CLIENT_ID,
    clientSecret: DISCORD_CLIENT_SECRET,
    callbackURL: `${BASE_URL}/auth/discord/callback`,
    scope: ['identify']
  }, (accessToken, refreshToken, profile, done) => {
    return done(null, profile);
  }));

  passport.serializeUser((user, done) => done(null, user));
  passport.deserializeUser((user, done) => done(null, user));
}

app.use(cors({ origin: true, credentials: true }));
app.use(express.json());
app.use(session({
  secret: SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { secure: false, maxAge: 7 * 24 * 60 * 60 * 1000 }
}));

if (useDiscordAuth) {
  app.use(passport.initialize());
  app.use(passport.session());
}

function requireAuth(req, res, next) {
  if (req.isAuthenticated && req.isAuthenticated()) return next();
  if (req.session && req.session.demoUser) return next();
  return res.status(401).json({ error: 'Non authentifié' });
}

function getCurrentUser(req) {
  if (req.user) return req.user;
  if (req.session && req.session.demoUser) return req.session.demoUser;
  return null;
}

// Auth routes
if (useDiscordAuth) {
  app.get('/auth/discord', passport.authenticate('discord'));
  app.get('/auth/discord/callback',
    passport.authenticate('discord', { failureRedirect: '/?error=auth_failed' }),
    (req, res) => res.redirect('/')
  );
}

// Demo login (uses first available player)
app.post('/auth/demo', (req, res) => {
  const players = loadPlayers();
  const firstId = Object.keys(players)[0];
  if (!firstId) return res.status(404).json({ error: 'Aucun joueur trouvé' });
  const player = players[firstId];
  req.session.demoUser = { id: player.id, username: player.name, avatar: null, demo: true };
  res.json({ success: true, user: req.session.demoUser });
});

app.get('/auth/logout', (req, res) => {
  req.session.destroy();
  if (req.logout) req.logout(() => {});
  res.redirect('/');
});

app.get('/api/me', (req, res) => {
  const user = getCurrentUser(req);
  if (!user) return res.json({ user: null, discordAuthEnabled: useDiscordAuth });
  res.json({ user, discordAuthEnabled: useDiscordAuth });
});

// Player data
app.get('/api/player', requireAuth, (req, res) => {
  const user = getCurrentUser(req);
  const players = loadPlayers();
  const player = players[user.id];
  if (!player) return res.json({ player: null, isNew: true });

  const classData = classes[player.class] || null;
  const factionData = player.faction ? factions[player.faction] || null : null;
  const itemsData = loadJSON(ITEMS_PATH) || { items: {} };
  const familiarsData = loadJSON(FAMILIARS_PATH) || { familiars: {} };

  const inventoryDetails = {};
  if (player.inventory) {
    for (const [itemId, qty] of Object.entries(player.inventory)) {
      const itemInfo = itemsData.items[itemId] || { name: itemId, description: '', rarity: 'common', value: 0 };
      inventoryDetails[itemId] = { ...itemInfo, quantity: qty };
    }
  }

  res.json({
    player: {
      ...player,
      classData,
      factionData,
      inventoryDetails
    }
  });
});

// Leaderboard
app.get('/api/leaderboard', (req, res) => {
  const players = loadPlayers();
  const list = Object.values(players)
    .filter(p => p && p.name)
    .map(p => ({
      id: p.id,
      name: p.name,
      class: p.class,
      level: p.level || 1,
      experience: p.experience || 0,
      gold: p.gold || 0,
      reputation: p.reputation || 0,
      combatWins: p.combat?.wins || 0,
      combatLosses: p.combat?.losses || 0,
      questsCompleted: p.quests?.completed?.length || 0,
    }))
    .sort((a, b) => (b.level - a.level) || (b.experience - a.experience));
  res.json({ leaderboard: list });
});

// Game data
app.get('/api/gamedata', (req, res) => {
  const questsData = loadJSON(QUESTS_PATH) || { templates: [] };
  const itemsData = loadJSON(ITEMS_PATH) || { items: {} };
  res.json({
    classes,
    factions,
    monsters,
    quests: questsData.templates || [],
    itemCount: Object.keys(itemsData.items || {}).length
  });
});

// Server stats
app.get('/api/stats', (req, res) => {
  const players = loadPlayers();
  const list = Object.values(players).filter(p => p && p.name);
  const totalGold = list.reduce((sum, p) => sum + (p.gold || 0), 0);
  const totalWins = list.reduce((sum, p) => sum + (p.combat?.wins || 0), 0);
  const totalQuests = list.reduce((sum, p) => sum + (p.quests?.completed?.length || 0), 0);
  const classCounts = {};
  list.forEach(p => { classCounts[p.class] = (classCounts[p.class] || 0) + 1; });
  res.json({
    totalPlayers: list.length,
    totalGold,
    totalWins,
    totalQuests,
    classCounts
  });
});

// Serve React app
const clientBuild = path.join(__dirname, '../client/dist');
if (fs.existsSync(clientBuild)) {
  app.use(express.static(clientBuild));
  app.get('*', (req, res) => {
    res.sendFile(path.join(clientBuild, 'index.html'));
  });
} else {
  // Serve inline HTML during development
  app.get('/', (req, res) => {
    res.send(`<!DOCTYPE html>
<html><head><title>Medieval Kingdom Dashboard</title>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
</head><body>
<h1>Medieval Kingdom Dashboard - Backend Running</h1>
<p>Run <code>cd dashboard/client && npm install && npm run build</code> to build the frontend.</p>
</body></html>`);
  });
}

app.listen(PORT, '0.0.0.0', () => {
  console.log(`🏰 Medieval Kingdom Dashboard running on port ${PORT}`);
  console.log(`Discord auth: ${useDiscordAuth ? 'enabled' : 'disabled (demo mode)'}`);
});

{
  "name": "medieval-dashboard-client",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "dev": "vite --port 5173",
    "build": "vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^18.2.0",
    "react-dom": "^18.2.0",
    "react-router-dom": "^6.22.0"
