}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    proxy: {
      '/api': 'http://localhost:5000',
      '/auth': 'http://localhost:5000'
    }
  },
  build: {
    outDir: 'dist'
  }
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.jsx';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --gold: #FFD700;
  --gold-dark: #B8860B;
  --gold-light: #FFF0A0;
  --bg-dark: #0d0b07;
  --bg-mid: #1a1408;
  --bg-card: #1e1a0e;
  --bg-card2: #252018;
  --border: #3d3210;
  --border-gold: #5a4a10;
  --text: #e8d9b0;
  --text-muted: #8a7a50;
  --text-bright: #ffeebb;
  --red: #c0392b;
  --green: #27ae60;
  --blue: #2980b9;
  --purple: #8e44ad;
  --orange: #e67e22;
  --common: #aaa;
  --uncommon: #1eff00;
  --rare: #0070dd;
  --epic: #a335ee;
  --legendary: #ff8000;
  --radius: 8px;
  --shadow: 0 4px 24px rgba(0,0,0,0.6);
}

html, body {
  background: var(--bg-dark);
  color: var(--text);
  font-family: 'Crimson Text', Georgia, serif;
  font-size: 16px;
  min-height: 100vh;
}

h1, h2, h3, h4, .font-title {
  font-family: 'Cinzel', serif;
  color: var(--gold);
}

a { color: var(--gold); text-decoration: none; }
a:hover { color: var(--gold-light); }

/* Layout */
.layout {
  display: flex;
  min-height: 100vh;
}

.sidebar {
  width: 220px;
  background: var(--bg-mid);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  padding: 0;
  position: fixed;
  top: 0; left: 0; bottom: 0;
  z-index: 100;
}

.sidebar-logo {
  padding: 24px 20px 16px;
  border-bottom: 1px solid var(--border);
  text-align: center;
}

.sidebar-logo h2 {
  font-size: 1rem;
  letter-spacing: 0.05em;
  color: var(--gold);
  text-transform: uppercase;
}

.sidebar-logo .crown {
  font-size: 2rem;
  display: block;
  margin-bottom: 6px;
}

.sidebar-nav {
  flex: 1;
  padding: 12px 0;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 20px;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.15s;
  font-family: 'Cinzel', serif;
  font-size: 0.8rem;
  letter-spacing: 0.04em;
  border-left: 3px solid transparent;
  text-decoration: none;
}

.nav-item:hover {
  background: var(--bg-card);
  color: var(--text);
  border-left-color: var(--border-gold);
}

.nav-item.active {
  background: var(--bg-card);
  color: var(--gold);
  border-left-color: var(--gold);
}

.nav-item .icon { font-size: 1.1rem; width: 20px; text-align: center; }

.sidebar-user {
  padding: 16px 20px;
  border-top: 1px solid var(--border);
}

.sidebar-user .user-name {
  font-size: 0.85rem;
  color: var(--text);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-user .user-sub {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.logout-btn {
  display: block;
  margin-top: 8px;
  padding: 6px 12px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 0.75rem;
  font-family: 'Cinzel', serif;
  width: 100%;
  transition: all 0.15s;
}

.logout-btn:hover {
  border-color: var(--red);
  color: #e74c3c;
}

.main-content {
  margin-left: 220px;
  flex: 1;
  padding: 32px 36px;
  max-width: 1200px;
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  margin-bottom: 20px;
}

.card-title {
  font-family: 'Cinzel', serif;
  font-size: 0.9rem;
  color: var(--gold);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

/* Stat bar */
.stat-bar-wrap { margin-bottom: 12px; }
.stat-bar-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 4px;
}
.stat-bar-label span:last-child { color: var(--text); }
.stat-bar {
  height: 8px;
  background: var(--bg-dark);
  border-radius: 4px;
  overflow: hidden;
  border: 1px solid var(--border);
}
.stat-bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.5s ease;
}
.bar-hp { background: linear-gradient(90deg, #c0392b, #e74c3c); }
.bar-mana { background: linear-gradient(90deg, #1a5276, #2980b9); }
.bar-xp { background: linear-gradient(90deg, #7d6608, #f1c40f); }

/* Stat grid */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  gap: 12px;
}

.stat-box {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 10px;
  text-align: center;
}

.stat-box .stat-val {
  font-size: 1.5rem;
  font-family: 'Cinzel', serif;
  color: var(--text-bright);
  display: block;
}

.stat-box .stat-name {
  font-size: 0.72rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: block;
  margin-top: 4px;
}

/* Badge / rarity */
.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 20px;
  font-size: 0.7rem;
  font-family: 'Cinzel', serif;
  letter-spacing: 0.04em;
  font-weight: 600;
}
.badge-common { background: #2a2a2a; color: var(--common); border: 1px solid #555; }
.badge-uncommon { background: #0e2a0e; color: var(--uncommon); border: 1px solid #1eff00; }
.badge-rare { background: #0e1e2a; color: var(--rare); border: 1px solid #0070dd; }
.badge-epic { background: #1a0e2a; color: var(--epic); border: 1px solid #a335ee; }
.badge-legendary { background: #2a1a0e; color: var(--legendary); border: 1px solid #ff8000; }

/* Table */
.table { width: 100%; border-collapse: collapse; }
.table th {
  font-family: 'Cinzel', serif;
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  text-align: left;
}
.table td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  font-size: 0.95rem;
}
.table tr:last-child td { border-bottom: none; }
.table tr:hover td { background: var(--bg-card2); }
.table .rank { color: var(--gold); font-family: 'Cinzel', serif; font-weight: 700; }

/* Loading / error */
.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 16px;
  min-height: 300px;
  color: var(--text-muted);
  font-size: 1.1rem;
}

.spinner {
  width: 40px; height: 40px;
  border: 3px solid var(--border);
  border-top-color: var(--gold);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

/* Login page */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at center, #1a1408 0%, #0d0b07 70%);
  position: relative;
  overflow: hidden;
}

.login-page::before {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffd700' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}

.login-card {
  position: relative;
  background: var(--bg-card);
  border: 1px solid var(--border-gold);
  border-radius: 12px;
  padding: 48px 40px;
  width: 380px;
  text-align: center;
  box-shadow: 0 8px 48px rgba(0,0,0,0.8), 0 0 60px rgba(255,215,0,0.05);
}

.login-crown { font-size: 3.5rem; display: block; margin-bottom: 16px; }

.login-card h1 {
  font-size: 1.4rem;
  margin-bottom: 6px;
  letter-spacing: 0.08em;
}

.login-card p {
  color: var(--text-muted);
  margin-bottom: 32px;
  font-size: 0.95rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 24px;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  font-family: 'Cinzel', serif;
  font-size: 0.85rem;
  letter-spacing: 0.04em;
  transition: all 0.2s;
  text-decoration: none;
  width: 100%;
  margin-bottom: 12px;
}

.btn-discord {
  background: #5865F2;
  color: white;
}

.btn-discord:hover { background: #4752C4; color: white; }

.btn-demo {
  background: var(--bg-card2);
  color: var(--text-muted);
  border: 1px solid var(--border);
}

.btn-demo:hover {
  background: var(--bg-dark);
  color: var(--text);
  border-color: var(--border-gold);
}

.btn-gold {
  background: linear-gradient(135deg, #b8860b, #ffd700);
  color: #0d0b07;
}

.btn-gold:hover { filter: brightness(1.1); }

/* Page header */
.page-header {
  margin-bottom: 28px;
}

.page-header h1 {
  font-size: 1.6rem;
  letter-spacing: 0.06em;
  margin-bottom: 4px;
}

.page-header p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* Character card */
.char-header {
  display: flex;
  gap: 20px;
  align-items: flex-start;
  margin-bottom: 20px;
}

.char-avatar {
  width: 80px; height: 80px;
  background: var(--bg-dark);
  border: 2px solid var(--border-gold);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  flex-shrink: 0;
}

.char-info h2 {
  font-size: 1.3rem;
  margin-bottom: 4px;
}

.char-meta {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 6px;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border-radius: 20px;
  font-size: 0.78rem;
  font-family: 'Cinzel', serif;
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text);
}

.pill-gold { border-color: var(--gold-dark); color: var(--gold); }
.pill-blue { border-color: #1a5276; color: #5dade2; }
.pill-green { border-color: #1e8449; color: #58d68d; }
.pill-purple { border-color: #6c3483; color: #c39bd3; }

/* Inventory items */
.inv-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 12px;
}

.inv-item {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 12px;
  transition: border-color 0.15s;
}

.inv-item:hover { border-color: var(--border-gold); }

.inv-item-name {
  font-size: 0.9rem;
  color: var(--text-bright);
  margin-bottom: 4px;
  font-weight: 600;
}

.inv-item-desc {
  font-size: 0.78rem;
  color: var(--text-muted);
  margin-bottom: 8px;
  line-height: 1.4;
}

.inv-item-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Quest card */
.quest-card {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 12px;
  transition: border-color 0.15s;
}

.quest-card:hover { border-color: var(--border-gold); }
.quest-card.active-quest { border-color: var(--gold-dark); background: #1a1505; }

.quest-title {
  font-family: 'Cinzel', serif;
  font-size: 0.9rem;
  color: var(--text-bright);
  margin-bottom: 6px;
  display: flex;
  justify-content: space-between;
}

.quest-desc { font-size: 0.88rem; color: var(--text-muted); line-height: 1.5; margin-bottom: 10px; }

.quest-rewards {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.reward-pill {
  font-size: 0.75rem;
  padding: 2px 8px;
  border-radius: 20px;
  background: var(--bg-card2);
  border: 1px solid var(--border);
  color: var(--text);
}

/* Stat number highlight */
.num-gold { color: var(--gold); }
.num-green { color: #58d68d; }
.num-red { color: #e74c3c; }
.num-blue { color: #5dade2; }

/* Compact info rows */
.info-row {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.9rem;
}
.info-row:last-child { border-bottom: none; }
.info-row label { color: var(--text-muted); }
.info-row value { color: var(--text-bright); font-weight: 600; }

/* Faction card */
.faction-card {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  text-align: center;
}

.faction-emoji { font-size: 2.5rem; display: block; margin-bottom: 8px; }

.faction-name {
  font-family: 'Cinzel', serif;
  font-size: 1rem;
  color: var(--gold);
  margin-bottom: 6px;
}

.faction-desc { font-size: 0.85rem; color: var(--text-muted); line-height: 1.5; }

/* Overview stat boxes */
.overview-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.overview-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
}

.overview-icon { font-size: 2rem; }
.overview-label { font-size: 0.75rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.05em; font-family: 'Cinzel', serif; }
.overview-val { font-size: 1.6rem; font-family: 'Cinzel', serif; color: var(--text-bright); }

/* Responsive */
@media (max-width: 768px) {
  .sidebar { width: 60px; }
  .nav-item span:not(.icon) { display: none; }
  .sidebar-logo h2 { display: none; }
  .sidebar-user .user-name, .sidebar-user .user-sub { display: none; }
  .main-content { margin-left: 60px; padding: 20px 16px; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
}

/* Empty state */
.empty-state {
  text-align: center;
  padding: 40px 20px;
  color: var(--text-muted);
}
.empty-state .empty-icon { font-size: 3rem; display: block; margin-bottom: 12px; }
.empty-state p { font-size: 0.95rem; }

/* No character */
.no-char {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 48px;
  text-align: center;
}

.no-char h2 { margin-bottom: 12px; }
.no-char p { color: var(--text-muted); }

import React, { useState, useEffect, createContext, useContext } from 'react';
import { BrowserRouter, Routes, Route, NavLink, Navigate } from 'react-router-dom';

import CharacterPage from './pages/CharacterPage.jsx';
import InventoryPage from './pages/InventoryPage.jsx';
import QuestsPage from './pages/QuestsPage.jsx';
import LeaderboardPage from './pages/LeaderboardPage.jsx';
import OverviewPage from './pages/OverviewPage.jsx';
import LoginPage from './pages/LoginPage.jsx';

const API = '';

export const UserContext = createContext(null);

function useUser() {
  return useContext(UserContext);
}

function Sidebar({ user }) {
  const initial = user?.username?.[0]?.toUpperCase() || '?';

  const handleLogout = () => {
    window.location.href = '/auth/logout';
  };

  return (
    <aside className="sidebar">
      <div className="sidebar-logo">
        <span className="crown">⚔️</span>
        <h2>Kingdom</h2>
      </div>
      <nav className="sidebar-nav">
        <NavLink to="/" end className={({ isActive }) => 'nav-item' + (isActive ? ' active' : '')}>
          <span className="icon">🏰</span>
          <span>Accueil</span>
        </NavLink>
        <NavLink to="/character" className={({ isActive }) => 'nav-item' + (isActive ? ' active' : '')}>
          <span className="icon">⚔️</span>
          <span>Personnage</span>
        </NavLink>
        <NavLink to="/inventory" className={({ isActive }) => 'nav-item' + (isActive ? ' active' : '')}>
          <span className="icon">🎒</span>
          <span>Inventaire</span>
        </NavLink>
        <NavLink to="/quests" className={({ isActive }) => 'nav-item' + (isActive ? ' active' : '')}>
          <span className="icon">📜</span>
          <span>Quêtes</span>
        </NavLink>
        <NavLink to="/leaderboard" className={({ isActive }) => 'nav-item' + (isActive ? ' active' : '')}>
          <span className="icon">🏆</span>
          <span>Classement</span>
        </NavLink>
      </nav>
      <div className="sidebar-user">
        <div className="user-name">{user?.username || 'Aventurier'}</div>
        <div className="user-sub">{user?.demo ? 'Mode démo' : 'Connecté via Discord'}</div>
        <button className="logout-btn" onClick={handleLogout}>Déconnexion</button>
      </div>
    </aside>
  );
}

export default function App() {
  const [user, setUser] = useState(undefined);
  const [discordAuthEnabled, setDiscordAuthEnabled] = useState(false);

  useEffect(() => {
    fetch(`${API}/api/me`, { credentials: 'include' })
      .then(r => r.json())
      .then(data => {
        setUser(data.user || null);
        setDiscordAuthEnabled(data.discordAuthEnabled || false);
      })
      .catch(() => setUser(null));
  }, []);

  if (user === undefined) {
    return (
      <div className="loading" style={{ minHeight: '100vh' }}>
        <div className="spinner"></div>
        <span>Chargement du royaume...</span>
      </div>
    );
  }

  if (!user) {
    return (
      <UserContext.Provider value={{ user: null, discordAuthEnabled }}>
        <LoginPage onLogin={(u) => setUser(u)} discordAuthEnabled={discordAuthEnabled} />
      </UserContext.Provider>
    );
  }

  return (
    <UserContext.Provider value={{ user, discordAuthEnabled }}>
      <BrowserRouter>
        <div className="layout">
          <Sidebar user={user} />
          <main className="main-content">
            <Routes>
              <Route path="/" element={<OverviewPage />} />
              <Route path="/character" element={<CharacterPage />} />
              <Route path="/inventory" element={<InventoryPage />} />
              <Route path="/quests" element={<QuestsPage />} />
              <Route path="/leaderboard" element={<LeaderboardPage />} />
              <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
          </main>
        </div>
      </BrowserRouter>
    </UserContext.Provider>
  );
}

import React, { useState } from 'react';

export default function LoginPage({ onLogin, discordAuthEnabled }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleDemo = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await fetch('/auth/demo', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' }
      });
      const data = await res.json();
      if (data.success) {
        onLogin(data.user);
      } else {
        setError(data.error || 'Erreur de connexion');
      }
    } catch {
      setError('Impossible de se connecter au serveur');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-card">
        <span className="login-crown">👑</span>
        <h1>Medieval Kingdom</h1>
        <p>Tableau de bord des aventuriers du royaume</p>

        {discordAuthEnabled && (
          <a href="/auth/discord" className="btn btn-discord">
            <svg width="20" height="20" viewBox="0 0 71 55" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M60.1045 4.8978C55.5792 2.8214 50.7265 1.2916 45.6527 0.41542C45.5603 0.39851 45.468 0.440769 45.4204 0.525289C44.7963 1.6353 44.105 3.0834 43.6209 4.2216C38.1637 3.4046 32.7345 3.4046 27.3892 4.2216C26.905 3.0581 26.1886 1.6353 25.5617 0.525289C25.5141 0.443589 25.4218 0.40133 25.3294 0.41542C20.2584 1.2888 15.4057 2.8186 10.8776 4.8978C10.8384 4.9147 10.8048 4.9429 10.7825 4.9795C1.57795 18.7309 -0.943561 32.1443 0.293408 45.3914C0.299005 45.4562 0.335386 45.5182 0.385761 45.5576C6.45866 50.0174 12.3413 52.7249 18.1147 54.5195C18.2071 54.5477 18.305 54.5139 18.3638 54.4378C19.7295 52.5728 20.9469 50.6063 21.9907 48.5383C22.0523 48.4172 21.9935 48.2735 21.8676 48.2256C19.9366 47.4931 18.0979 46.6 16.3292 45.5858C16.1893 45.5041 16.1781 45.304 16.3068 45.2082C16.679 44.9293 17.0513 44.6391 17.4067 44.3461C17.471 44.2926 17.5606 44.2813 17.6362 44.3151C29.2558 49.6202 41.8354 49.6202 53.3179 44.3151C53.3935 44.2785 53.4831 44.2898 53.5502 44.3433C53.9057 44.6363 54.2779 44.9293 54.6529 45.2082C54.7816 45.304 54.7732 45.5041 54.6333 45.5858C52.8646 46.6197 51.0259 47.4931 49.0921 48.2228C48.9662 48.2707 48.9102 48.4172 48.9718 48.5383C50.038 50.6034 51.2554 52.5699 52.5959 54.435C52.6519 54.5139 52.7526 54.5477 52.845 54.5195C58.6464 52.7249 64.529 50.0174 70.6019 45.5576C70.6551 45.5182 70.6887 45.459 70.6943 45.3942C72.1747 30.0791 68.2147 16.7757 60.1968 4.9823C60.1772 4.9429 60.1437 4.9147 60.1045 4.8978Z" fill="white"/>
            </svg>
            Connexion via Discord
          </a>
        )}

        <button className="btn btn-demo" onClick={handleDemo} disabled={loading}>
          {loading ? '⏳ Connexion...' : '🎭 Connexion démo (premier joueur)'}
        </button>

        {error && <p style={{ color: '#e74c3c', fontSize: '0.85rem', marginTop: '8px' }}>{error}</p>}

        <div style={{ marginTop: '24px', fontSize: '0.8rem', color: 'var(--text-muted)', lineHeight: 1.6 }}>
          <p>🔒 Connectez-vous avec Discord pour accéder à votre personnage.</p>
          {!discordAuthEnabled && <p style={{ marginTop: '6px', color: '#e67e22' }}>⚙️ OAuth Discord non configuré — mode démo uniquement.</p>}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState, useContext } from 'react';
import { UserContext } from '../App.jsx';

const CLASS_EMOJI = { chevalier: '⚔️', mage: '🔮', voleur: '🗡️', barde: '🎵' };

export default function OverviewPage() {
  const { user } = useContext(UserContext);
  const [player, setPlayer] = useState(null);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      fetch('/api/player', { credentials: 'include' }).then(r => r.json()),
      fetch('/api/stats', { credentials: 'include' }).then(r => r.json())
    ]).then(([pd, sd]) => {
      setPlayer(pd.player);
      setStats(sd);
    }).finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="loading"><div className="spinner"></div><span>Chargement...</span></div>;

  const xpForNextLevel = player ? (player.level || 1) * 100 : 100;
  const xpPct = player ? Math.min(100, ((player.experience || 0) / xpForNextLevel) * 100) : 0;
  const hpPct = player ? Math.min(100, ((player.health || 0) / (player.maxHealth || 1)) * 100) : 0;
  const manaPct = player ? Math.min(100, ((player.mana || 0) / (player.maxMana || 1)) * 100) : 0;

  return (
    <div>
      <div className="page-header">
