                <div key={i} style={{ padding: '6px 0', fontSize: '0.88rem', borderBottom: '1px solid var(--border)', color: 'var(--text)' }}>✓ {b}</div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';

const RARITY_ORDER = { legendary: 0, epic: 1, rare: 2, uncommon: 3, common: 4 };
const TYPE_ICONS = {
  consumable: '🧪',
  weapon: '⚔️',
  armor: '🛡️',
  material: '🪨',
  quest: '📜',
  accessory: '💍',
};

function RarityBadge({ rarity }) {
  return <span className={`badge badge-${rarity || 'common'}`}>{rarity || 'common'}</span>;
}

export default function InventoryPage() {
  const [player, setPlayer] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [sort, setSort] = useState('rarity');

  useEffect(() => {
    fetch('/api/player', { credentials: 'include' })
      .then(r => r.json())
      .then(data => setPlayer(data.player))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="loading"><div className="spinner"></div><span>Chargement...</span></div>;

  if (!player) {
    return (
      <div>
        <div className="page-header"><h1>🎒 Inventaire</h1></div>
        <div className="no-char"><h2>Aucun personnage trouvé</h2></div>
      </div>
    );
  }

  const inv = player.inventoryDetails || {};
  const items = Object.entries(inv);

  const types = ['all', ...new Set(items.map(([, i]) => i.type).filter(Boolean))];

  let filtered = filter === 'all' ? items : items.filter(([, i]) => i.type === filter);

  filtered = filtered.sort((a, b) => {
    const [, ia] = a; const [, ib] = b;
    if (sort === 'rarity') return (RARITY_ORDER[ia.rarity] ?? 4) - (RARITY_ORDER[ib.rarity] ?? 4);
    if (sort === 'name') return (ia.name || '').localeCompare(ib.name || '');
    if (sort === 'value') return (ib.value || 0) - (ia.value || 0);
    if (sort === 'qty') return (ib.quantity || 0) - (ia.quantity || 0);
    return 0;
  });

  const totalValue = items.reduce((s, [, i]) => s + (i.value || 0) * (i.quantity || 1), 0);

  return (
    <div>
      <div className="page-header">
        <h1>🎒 Inventaire</h1>
        <p>{items.length} types d'objets — Valeur totale : <span className="num-gold">{totalValue.toLocaleString()} or</span></p>
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 12, marginBottom: 20, flexWrap: 'wrap', alignItems: 'center' }}>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {types.map(t => (
            <button key={t} onClick={() => setFilter(t)} style={{
              padding: '6px 14px', borderRadius: 20, border: '1px solid',
              borderColor: filter === t ? 'var(--gold)' : 'var(--border)',
              background: filter === t ? 'var(--bg-card2)' : 'transparent',
              color: filter === t ? 'var(--gold)' : 'var(--text-muted)',
              cursor: 'pointer', fontSize: '0.8rem', fontFamily: 'Cinzel, serif'
            }}>
              {TYPE_ICONS[t] || ''} {t === 'all' ? 'Tout' : t}
            </button>
          ))}
        </div>
        <div style={{ marginLeft: 'auto', display: 'flex', gap: 8, alignItems: 'center' }}>
          <label style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>Trier par :</label>
          <select value={sort} onChange={e => setSort(e.target.value)} style={{
            background: 'var(--bg-card)', border: '1px solid var(--border)', color: 'var(--text)',
            padding: '6px 10px', borderRadius: 'var(--radius)', fontSize: '0.85rem', fontFamily: 'Crimson Text, serif'
          }}>
            <option value="rarity">Rareté</option>
            <option value="name">Nom</option>
            <option value="value">Valeur</option>
            <option value="qty">Quantité</option>
          </select>
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="empty-state">
          <span className="empty-icon">🎒</span>
          <p>{filter === 'all' ? "Votre inventaire est vide. Complétez des quêtes pour obtenir des objets !" : "Aucun objet de ce type."}</p>
        </div>
      ) : (
        <div className="inv-grid">
          {filtered.map(([id, item]) => (
            <div key={id} className="inv-item">
              <div style={{ fontSize: '1.6rem', marginBottom: 6 }}>{TYPE_ICONS[item.type] || '📦'}</div>
              <div className="inv-item-name">{item.name || id}</div>
              <div className="inv-item-desc">{item.description || '—'}</div>
              <div className="inv-item-footer">
                <RarityBadge rarity={item.rarity} />
                <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                  x{item.quantity || 1}
                </span>
              </div>
              {item.value > 0 && (
                <div style={{ marginTop: 6, fontSize: '0.78rem', color: 'var(--gold)' }}>
                  💰 {item.value} or
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';

export default function QuestsPage() {
  const [player, setPlayer] = useState(null);
  const [gamedata, setGamedata] = useState(null);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState('active');

  useEffect(() => {
    Promise.all([
      fetch('/api/player', { credentials: 'include' }).then(r => r.json()),
      fetch('/api/gamedata', { credentials: 'include' }).then(r => r.json()),
    ]).then(([pd, gd]) => {
      setPlayer(pd.player);
      setGamedata(gd);
    }).finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="loading"><div className="spinner"></div><span>Chargement...</span></div>;
  if (!player) return <div><div className="page-header"><h1>📜 Quêtes</h1></div><div className="no-char"><h2>Aucun personnage trouvé</h2></div></div>;

  const activeQuest = player.quests?.active;
  const completedIds = player.quests?.completed || [];
  const allQuests = gamedata?.quests || [];

  const completedQuests = allQuests.filter(q => completedIds.includes(q.id));
  const availableQuests = allQuests.filter(q =>
    !completedIds.includes(q.id) &&
    (!q.requirements?.minLevel || (player.level || 1) >= q.requirements.minLevel) &&
    q.id !== activeQuest?.id
  );

  const tabs = [
    { id: 'active', label: '⚡ Active', count: activeQuest ? 1 : 0 },
    { id: 'available', label: '📋 Disponibles', count: availableQuests.length },
    { id: 'completed', label: '✅ Complétées', count: completedQuests.length },
  ];

  function renderQuestCard(quest, isActive = false) {
    return (
      <div key={quest.id} className={`quest-card${isActive ? ' active-quest' : ''}`}>
        <div className="quest-title">
          <span>{quest.title}</span>
          {quest.requirements?.minLevel && <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Niv. {quest.requirements.minLevel}+</span>}
        </div>
        <div className="quest-desc">{quest.description}</div>
        <div className="quest-rewards">
          {quest.rewards?.experience && <span className="reward-pill">⭐ {quest.rewards.experience} XP</span>}
          {quest.rewards?.gold && <span className="reward-pill">💰 {quest.rewards.gold} or</span>}
          {quest.rewards?.items?.map((item, i) => (
            <span key={i} className="reward-pill">📦 {item}</span>
          ))}
          {quest.duration && <span className="reward-pill">⏱️ {quest.duration} min</span>}
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="page-header">
        <h1>📜 Quêtes</h1>
        <p>{completedIds.length} complétées sur {allQuests.length} disponibles dans le royaume</p>
      </div>

      {/* Progress bar */}
      <div className="card" style={{ marginBottom: 20 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6, fontSize: '0.85rem' }}>
          <span style={{ color: 'var(--text-muted)' }}>Progression des quêtes</span>
          <span>{Math.round((completedIds.length / Math.max(allQuests.length, 1)) * 100)}%</span>
        </div>
        <div className="stat-bar" style={{ height: 12 }}>
          <div className="stat-bar-fill bar-xp" style={{ width: `${(completedIds.length / Math.max(allQuests.length, 1)) * 100}%` }}></div>
        </div>
        <div style={{ display: 'flex', gap: 20, marginTop: 12 }}>
          <span style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>📜 Complétées aujourd'hui : <strong style={{ color: 'var(--text)' }}>{player.quests?.completedToday || 0}/10</strong></span>
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 20 }}>
        {tabs.map(t => (
          <button key={t.id} onClick={() => setTab(t.id)} style={{
            padding: '8px 18px', borderRadius: 'var(--radius)', border: '1px solid',
            borderColor: tab === t.id ? 'var(--gold)' : 'var(--border)',
            background: tab === t.id ? 'var(--bg-card2)' : 'transparent',
            color: tab === t.id ? 'var(--gold)' : 'var(--text-muted)',
            cursor: 'pointer', fontFamily: 'Cinzel, serif', fontSize: '0.8rem'
          }}>
            {t.label} {t.count > 0 && <span style={{ marginLeft: 4, background: 'var(--gold)', color: '#000', borderRadius: 10, padding: '1px 6px', fontSize: '0.7rem' }}>{t.count}</span>}
          </button>
        ))}
      </div>

      {/* Content */}
      {tab === 'active' && (
        activeQuest ? (
          <div>
            <div style={{ marginBottom: 12, fontSize: '0.85rem', color: 'var(--text-muted)' }}>
              Quête commencée le {activeQuest.startTime ? new Date(activeQuest.startTime).toLocaleDateString('fr-FR') : '—'}
            </div>
            {renderQuestCard(activeQuest, true)}
          </div>
        ) : (
          <div className="empty-state">
            <span className="empty-icon">⚡</span>
            <p>Aucune quête active. Utilisez <code>/quete</code> sur Discord pour en lancer une.</p>
          </div>
        )
      )}

      {tab === 'available' && (
        availableQuests.length === 0 ? (
          <div className="empty-state">
            <span className="empty-icon">📋</span>
            <p>Aucune quête disponible pour votre niveau.</p>
          </div>
        ) : (
          <div>{availableQuests.map(q => renderQuestCard(q))}</div>
        )
      )}

      {tab === 'completed' && (
        completedQuests.length === 0 ? (
          <div className="empty-state">
            <span className="empty-icon">✅</span>
            <p>Aucune quête complétée pour l'instant.</p>
          </div>
        ) : (
          <div>
            {completedQuests.map(q => (
              <div key={q.id} className="quest-card" style={{ opacity: 0.7 }}>
                <div className="quest-title">
                  <span>✅ {q.title}</span>
                </div>
                <div className="quest-desc">{q.description}</div>
              </div>
            ))}
          </div>
        )
      )}
    </div>
  );
}

import React, { useEffect, useState, useContext } from 'react';
import { UserContext } from '../App.jsx';

const CLASS_EMOJI = { chevalier: '⚔️', mage: '🔮', voleur: '🗡️', barde: '🎵' };

const RANK_STYLES = [
  { color: '#FFD700', icon: '🥇' },
  { color: '#C0C0C0', icon: '🥈' },
  { color: '#CD7F32', icon: '🥉' },
];

export default function LeaderboardPage() {
  const { user } = useContext(UserContext);
  const [leaderboard, setLeaderboard] = useState([]);
  const [loading, setLoading] = useState(true);
  const [sortBy, setSortBy] = useState('level');

  useEffect(() => {
    fetch('/api/leaderboard', { credentials: 'include' })
      .then(r => r.json())
      .then(data => setLeaderboard(data.leaderboard || []))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="loading"><div className="spinner"></div><span>Chargement...</span></div>;

  const sortOptions = [
    { key: 'level', label: 'Niveau' },
    { key: 'experience', label: 'XP' },
    { key: 'gold', label: 'Or' },
    { key: 'combatWins', label: 'Victoires' },
    { key: 'questsCompleted', label: 'Quêtes' },
    { key: 'reputation', label: 'Réputation' },
  ];

  const sorted = [...leaderboard].sort((a, b) => (b[sortBy] || 0) - (a[sortBy] || 0));
  const myRank = sorted.findIndex(p => p.id === user?.id) + 1;

  return (
    <div>
      <div className="page-header">
        <h1>🏆 Classement</h1>
        <p>
          {leaderboard.length} aventuriers dans le royaume
          {myRank > 0 && <span> — Vous êtes <span style={{ color: 'var(--gold)' }}>#{myRank}</span></span>}
        </p>
      </div>

      {/* Sort buttons */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 20, flexWrap: 'wrap' }}>
        {sortOptions.map(opt => (
          <button key={opt.key} onClick={() => setSortBy(opt.key)} style={{
            padding: '6px 14px', borderRadius: 20, border: '1px solid',
            borderColor: sortBy === opt.key ? 'var(--gold)' : 'var(--border)',
            background: sortBy === opt.key ? 'var(--bg-card2)' : 'transparent',
            color: sortBy === opt.key ? 'var(--gold)' : 'var(--text-muted)',
            cursor: 'pointer', fontSize: '0.78rem', fontFamily: 'Cinzel, serif'
          }}>
            {opt.label}
          </button>
        ))}
      </div>

      {/* Podium top 3 */}
      {sorted.length >= 3 && (
        <div style={{ display: 'flex', gap: 12, marginBottom: 24, justifyContent: 'center' }}>
          {[sorted[1], sorted[0], sorted[2]].map((player, idx) => {
            const actualRank = idx === 0 ? 2 : idx === 1 ? 1 : 3;
            const style = RANK_STYLES[actualRank - 1];
            const height = actualRank === 1 ? 120 : actualRank === 2 ? 90 : 70;
            return (
              <div key={player.id} style={{ textAlign: 'center', flex: 1, maxWidth: 180 }}>
                <div style={{ fontSize: '0.85rem', fontFamily: 'Cinzel', color: style.color, marginBottom: 4 }}>{CLASS_EMOJI[player.class] || '❓'} {player.name}</div>
                <div style={{
                  background: `linear-gradient(180deg, ${style.color}22, ${style.color}44)`,
                  border: `1px solid ${style.color}66`,
                  borderRadius: 'var(--radius) var(--radius) 0 0',
                  height, display: 'flex', alignItems: 'flex-start', justifyContent: 'center', paddingTop: 8,
                  fontSize: '1.5rem'
                }}>{style.icon}</div>
                <div style={{ background: 'var(--bg-card)', border: `1px solid ${style.color}44`, borderTop: 'none', padding: '6px', fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                  Niv. {player.level} • {player[sortBy]?.toLocaleString()} {sortOptions.find(o => o.key === sortBy)?.label}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Full table */}
      <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
        <table className="table">
          <thead>
            <tr>
              <th>#</th>
              <th>Aventurier</th>
              <th>Classe</th>
              <th>Niveau</th>
              <th>Or</th>
              <th>Victoires</th>
              <th>Quêtes</th>
              <th>Réputation</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((player, i) => {
              const isMe = player.id === user?.id;
              return (
                <tr key={player.id} style={isMe ? { background: 'rgba(255,215,0,0.05)' } : {}}>
                  <td>
                    <span className="rank" style={{ color: RANK_STYLES[i]?.color || 'var(--text-muted)' }}>
                      {RANK_STYLES[i]?.icon || `#${i + 1}`}
                    </span>
                  </td>
                  <td>
                    <span style={{ color: isMe ? 'var(--gold)' : 'var(--text-bright)', fontWeight: isMe ? 700 : 400 }}>
                      {player.name} {isMe && <span style={{ fontSize: '0.7rem', color: 'var(--gold)', fontFamily: 'Cinzel' }}>←</span>}
                    </span>
                  </td>
                  <td>{CLASS_EMOJI[player.class] || '❓'} {player.class}</td>
                  <td><span className="num-gold">{player.level}</span></td>
                  <td>{(player.gold || 0).toLocaleString()}</td>
                  <td><span className="num-green">{player.combatWins}</span></td>
                  <td>{player.questsCompleted}</td>
                  <td>{player.reputation}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

