require('dotenv').config({ path: '../MedievalKingdom/MedievalKingdom/.env' });

const express = require('express');
const session = require('express-session');
const passport = require('passport');
const DiscordStrategy = require('passport-discord').Strategy;
const cors = require('cors');
const path = require('path');
const fs = require('fs');
const https = require('https');

const app = express();
const PORT = process.env.DASHBOARD_PORT || 5000;

const DB_PATH = path.join(__dirname, '../../MedievalKingdom/MedievalKingdom/database');
const ITEMS_PATH = path.join(DB_PATH, 'items.json');
const QUESTS_PATH = path.join(DB_PATH, 'quests.json');
const FAMILIARS_PATH = path.join(DB_PATH, 'familiars.json');
const PLAYERS_PATH = path.join(DB_PATH, 'players.json');

const { classes, factions, monsters } = require('../../MedievalKingdom/MedievalKingdom/systems/gameData.js');

const DISCORD_CLIENT_ID = process.env.DISCORD_CLIENT_ID || '';
const DISCORD_CLIENT_SECRET = process.env.DISCORD_CLIENT_SECRET || '';
const BOT_TOKEN = process.env.DISCORD_TOKEN || '';
const GUILD_ID = process.env.GUILD_ID || '';
const SESSION_SECRET = process.env.SESSION_SECRET || 'medieval-kingdom-secret-2024';
const BASE_URL = process.env.BASE_URL || `https://${process.env.REPLIT_DEV_DOMAIN || `localhost:${PORT}`}`;
const useDiscordAuth = !!(DISCORD_CLIENT_ID && DISCORD_CLIENT_SECRET);

// ─── Helpers ────────────────────────────────────────────────────────────────

function loadJSON(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch {
    return null;
  }
}

// Always reads fresh from disk — no cache
function loadPlayers() {
  return loadJSON(PLAYERS_PATH) || {};
}

// Call Discord REST API with bot token
function discordFetch(endpoint) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'discord.com',
      path: `/api/v10${endpoint}`,
      method: 'GET',
      headers: {
        'Authorization': `Bot ${BOT_TOKEN}`,
        'Content-Type': 'application/json',
        'User-Agent': 'MedievalKingdomDashboard/1.0'
      }
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve({ status: res.statusCode, body: JSON.parse(data) }); }
        catch { resolve({ status: res.statusCode, body: null }); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

// Check if a user is a member of the guild
async function isGuildMember(userId) {
  if (!BOT_TOKEN || !GUILD_ID) return true; // skip check if not configured
  try {
    const res = await discordFetch(`/guilds/${GUILD_ID}/members/${userId}`);
    return res.status === 200;
  } catch {
    return true; // fail open if Discord API is unreachable
  }
}

// Fetch guild member info (nick + guild avatar)
async function getGuildMember(userId) {
  if (!BOT_TOKEN || !GUILD_ID) return null;
  try {
    const res = await discordFetch(`/guilds/${GUILD_ID}/members/${userId}`);
    if (res.status === 200) return res.body;
    return null;
  } catch {
    return null;
  }
}

// Build avatar URL for a Discord user
function buildAvatarUrl(userId, avatarHash, size = 128) {
  if (!avatarHash) return null;
  const ext = avatarHash.startsWith('a_') ? 'gif' : 'png';
  return `https://cdn.discordapp.com/avatars/${userId}/${avatarHash}.${ext}?size=${size}`;
}

// Build guild member avatar URL
function buildMemberAvatarUrl(guildId, userId, avatarHash, size = 128) {
  if (!avatarHash) return null;
  const ext = avatarHash.startsWith('a_') ? 'gif' : 'png';
  return `https://cdn.discordapp.com/guilds/${guildId}/users/${userId}/avatars/${avatarHash}.${ext}?size=${size}`;
}

// Default Discord avatar (based on discriminator or user id)
function defaultAvatarUrl(userId) {
  const index = (BigInt(userId) >> 22n) % 6n;
  return `https://cdn.discordapp.com/embed/avatars/${index}.png`;
}

// Enrich a user object with guild member data (nick + avatar)
async function enrichUserWithGuild(profile) {
  const member = await getGuildMember(profile.id);
  let avatarUrl = buildAvatarUrl(profile.id, profile.avatar) || defaultAvatarUrl(profile.id);
  let displayName = profile.username;

  if (member) {
    // Prefer guild-specific avatar, then global avatar, then default
    if (member.avatar) {
      avatarUrl = buildMemberAvatarUrl(GUILD_ID, profile.id, member.avatar) || avatarUrl;
    }
    // Prefer server nickname over global username
    if (member.nick) {
      displayName = member.nick;
    }
  }

  return {
    id: profile.id,
    username: profile.username,
    displayName,
    avatar: profile.avatar,
    avatarUrl,
    globalName: profile.global_name || profile.username,
  };
}

// ─── Passport ───────────────────────────────────────────────────────────────

if (useDiscordAuth) {
  passport.use(new DiscordStrategy({
    clientID: DISCORD_CLIENT_ID,
    clientSecret: DISCORD_CLIENT_SECRET,
    callbackURL: `${BASE_URL}/auth/discord/callback`,
    scope: ['identify']
  }, (accessToken, refreshToken, profile, done) => {
    return done(null, profile);
  }));

  passport.serializeUser((user, done) => done(null, user));
  passport.deserializeUser((user, done) => done(null, user));
}

// ─── Middleware ──────────────────────────────────────────────────────────────

app.use(cors({ origin: true, credentials: true }));
app.use(express.json());
app.use(session({
  secret: SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { secure: false, maxAge: 7 * 24 * 60 * 60 * 1000 }
}));

if (useDiscordAuth) {
  app.use(passport.initialize());
  app.use(passport.session());
}

function requireAuth(req, res, next) {
  if (req.isAuthenticated && req.isAuthenticated()) return next();
  if (req.session && req.session.demoUser) return next();
  return res.status(401).json({ error: 'Non authentifié' });
}

function getCurrentUser(req) {
  if (req.user) return req.user;
  if (req.session && req.session.demoUser) return req.session.demoUser;
  return null;
}

// ─── Auth routes ─────────────────────────────────────────────────────────────

if (useDiscordAuth) {
  app.get('/auth/discord', passport.authenticate('discord'));

  app.get('/auth/discord/callback',
    passport.authenticate('discord', { failureRedirect: '/?error=auth_failed' }),
    async (req, res) => {
      try {
        // Check guild membership
        const isMember = await isGuildMember(req.user.id);
        if (!isMember) {
          req.logout(() => {});
          return res.redirect('/?error=not_member');
        }

        // Enrich session with real avatar + display name
        const enriched = await enrichUserWithGuild(req.user);
        req.session.enrichedUser = enriched;

        res.redirect('/');
      } catch (err) {
        console.error('Callback error:', err);
        res.redirect('/');
      }
    }
  );
}

// Demo login
app.post('/auth/demo', (req, res) => {
  const players = loadPlayers();
  const firstId = Object.keys(players)[0];
  if (!firstId) return res.status(404).json({ error: 'Aucun joueur trouvé' });
  const player = players[firstId];
  req.session.demoUser = {
    id: player.id,
    username: player.name,
    displayName: player.name,
    avatarUrl: null,
    demo: true
  };
  res.json({ success: true, user: req.session.demoUser });
});

app.get('/auth/logout', (req, res) => {
  req.session.destroy();
  if (req.logout) req.logout(() => {});
  res.redirect('/');
});

// ─── API routes ──────────────────────────────────────────────────────────────

app.get('/api/me', (req, res) => {
  const rawUser = getCurrentUser(req);
  if (!rawUser) return res.json({ user: null, discordAuthEnabled: useDiscordAuth });

  // Prefer enriched user data (with real avatar) stored after callback
  const enriched = req.session?.enrichedUser;
  const user = enriched || rawUser;

  res.json({ user, discordAuthEnabled: useDiscordAuth });
});

// Player data — always reads fresh from disk
app.get('/api/player', requireAuth, (req, res) => {
  const rawUser = getCurrentUser(req);
  const user = req.session?.enrichedUser || rawUser;
  const players = loadPlayers(); // fresh read every time
  const player = players[user.id];
  if (!player) return res.json({ player: null, isNew: true });

  const classData = classes[player.class] || null;
  const factionData = player.faction ? factions[player.faction] || null : null;
  const itemsData = loadJSON(ITEMS_PATH) || { items: {} };

  const inventoryDetails = {};
  if (player.inventory) {
    for (const [itemId, qty] of Object.entries(player.inventory)) {
      const itemInfo = itemsData.items[itemId] || { name: itemId, description: '', rarity: 'common', value: 0 };
      inventoryDetails[itemId] = { ...itemInfo, quantity: qty };
    }
  }

  res.json({
    player: {
      ...player,
      classData,
      factionData,
      inventoryDetails,
      discordAvatarUrl: user.avatarUrl || null,
      discordDisplayName: user.displayName || player.name
    }
  });
});

// Leaderboard — fresh read + fetch Discord avatars for all players
app.get('/api/leaderboard', async (req, res) => {
  const players = loadPlayers(); // fresh read
  const list = Object.values(players)
    .filter(p => p && p.name)
    .map(p => ({
      id: p.id,
      name: p.name,
      class: p.class,
      level: p.level || 1,
      experience: p.experience || 0,
      gold: p.gold || 0,
      reputation: p.reputation || 0,
      combatWins: p.combat?.wins || 0,
      combatLosses: p.combat?.losses || 0,
      questsCompleted: p.quests?.completed?.length || 0,
      avatarUrl: null
    }))
    .sort((a, b) => (b.level - a.level) || (b.experience - a.experience));

  // Fetch Discord avatars in parallel (with bot token)
  if (BOT_TOKEN && GUILD_ID && list.length > 0) {
    await Promise.all(list.map(async (p) => {
      try {
        const member = await getGuildMember(p.id);
        if (member) {
          const user = member.user || {};
          // Guild avatar takes priority
          if (member.avatar) {
            p.avatarUrl = buildMemberAvatarUrl(GUILD_ID, p.id, member.avatar, 64);
          } else if (user.avatar) {
            p.avatarUrl = buildAvatarUrl(p.id, user.avatar, 64);
          } else {
            p.avatarUrl = defaultAvatarUrl(p.id);
          }
          // Use Discord display name if available
          if (member.nick) p.discordNick = member.nick;
          else if (user.global_name) p.discordNick = user.global_name;
        }
      } catch {
        // Leave avatarUrl null
      }
    }));
  }

  res.json({ leaderboard: list });
});

// Game data
app.get('/api/gamedata', (req, res) => {
  const questsData = loadJSON(QUESTS_PATH) || { templates: [] };
  const itemsData = loadJSON(ITEMS_PATH) || { items: {} };
  res.json({
    classes,
    factions,
    monsters,
    quests: questsData.templates || [],
    itemCount: Object.keys(itemsData.items || {}).length
  });
});

// Server stats — fresh read
app.get('/api/stats', (req, res) => {
  const players = loadPlayers();
  const list = Object.values(players).filter(p => p && p.name);
  const totalGold = list.reduce((sum, p) => sum + (p.gold || 0), 0);
  const totalWins = list.reduce((sum, p) => sum + (p.combat?.wins || 0), 0);
  const totalQuests = list.reduce((sum, p) => sum + (p.quests?.completed?.length || 0), 0);
  const classCounts = {};
  list.forEach(p => { classCounts[p.class] = (classCounts[p.class] || 0) + 1; });
  res.json({ totalPlayers: list.length, totalGold, totalWins, totalQuests, classCounts });
});

// ─── Serve React build ───────────────────────────────────────────────────────

const clientBuild = path.join(__dirname, '../client/dist');
if (fs.existsSync(clientBuild)) {
  app.use(express.static(clientBuild));
  app.get('*', (req, res) => res.sendFile(path.join(clientBuild, 'index.html')));
}

app.listen(PORT, '0.0.0.0', () => {
  console.log(`🏰 Medieval Kingdom Dashboard running on port ${PORT}`);
  console.log(`Discord auth: ${useDiscordAuth ? 'enabled' : 'disabled (demo mode)'}`);
  console.log(`Guild check: ${BOT_TOKEN && GUILD_ID ? `enabled (guild ${GUILD_ID})` : 'disabled'}`);
});

