   148→/**
   149→ * Récupère les statistiques générales de la base de données
   150→ */
   151→function getDatabaseStats() {
   152→  const players = Object.values(loadPlayers());
   153→
   154→  if (players.length === 0) {
   155→    return {
   156→      totalPlayers: 0,
   157→      averageLevel: 0,
   158→      totalGold: 0,
   159→      activePlayers: 0,
   160→    };
   161→  }
   162→
   163→  const totalLevel = players.reduce((sum, player) => sum + player.level, 0);
   164→  const totalGold = players.reduce((sum, player) => sum + player.gold, 0);
   165→
   166→  // Joueurs actifs dans les dernières 24 heures
   167→  const yesterday = new Date();
   168→  yesterday.setDate(yesterday.getDate() - 1);
   169→  const activePlayers = players.filter(
   170→    (player) => new Date(player.lastActive) > yesterday,
   171→  ).length;
   172→
   173→  // Statistiques par classe
   174→  const classCounts = {};
   175→  players.forEach((player) => {
   176→    classCounts[player.class] = (classCounts[player.class] || 0) + 1;
   177→  });
   178→
   179→  // Statistiques par faction
   180→  const factionCounts = {};
   181→  players.forEach((player) => {
   182→    if (player.faction) {
   183→      factionCounts[player.faction] = (factionCounts[player.faction] || 0) + 1;
   184→    }
   185→  });
   186→
   187→  return {
   188→    totalPlayers: players.length,
   189→    averageLevel: (totalLevel / players.length).toFixed(1),
   190→    totalGold: totalGold,
   191→    activePlayers: activePlayers,
   192→    classCounts: classCounts,
   193→    factionCounts: factionCounts,
   194→    highestLevel: Math.max(...players.map((p) => p.level)),
   195→    richestPlayer: Math.max(...players.map((p) => p.gold)),
   196→  };
   197→}
   198→
   199→/**
   200→ * Nettoie les joueurs inactifs (non utilisé depuis X jours)
   201→ */
   202→function cleanupInactivePlayers(daysInactive = 30) {
   203→  const players = loadPlayers();
   204→  const cutoffDate = new Date();
   205→  cutoffDate.setDate(cutoffDate.getDate() - daysInactive);
   206→
   207→  let deletedCount = 0;
   208→
   209→  for (const [userId, player] of Object.entries(players)) {
   210→    const lastActive = new Date(player.lastActive);
   211→    if (lastActive < cutoffDate) {
   212→      delete players[userId];
   213→      deletedCount++;
   214→    }
   215→  }
