   227→/**
   228→ * Exporte les données des joueurs pour sauvegarde
   229→ */
   230→function exportPlayerData() {
   231→  const players = loadPlayers();
   232→  const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
   233→  const exportPath = path.join(
   234→    __dirname,
