   244→    return null;
   245→  }
   246→}
   247→
   248→/**
   249→ * Importe les données des joueurs depuis un fichier de sauvegarde
   250→ */
   251→function importPlayerData(filePath) {
   252→  try {
   253→    if (!fs.existsSync(filePath)) {
   254→      throw new Error("Fichier de sauvegarde introuvable");
   255→    }
   256→
   257→    const data = fs.readFileSync(filePath, "utf8");
   258→    const players = JSON.parse(data);
   259→
   260→    // Valider la structure des données
   261→    if (typeof players !== "object") {
   262→      throw new Error("Format de données invalide");
   263→    }
   264→
   265→    savePlayersData(players);
   266→    console.log(`Données importées depuis: ${filePath}`);
   267→    return Object.keys(players).length;
   268→  } catch (error) {
   269→    console.error("Erreur lors de l'import:", error);
   270→    return -1;
   271→  }
   272→}
   273→
   274→/**
   275→ * Corrige l'expérience des joueurs pour respecter la formule linéaire
   276→ */
   277→function fixPlayerExperience() {
   278→  const players = loadPlayers();
   279→  let fixedCount = 0;
   280→
   281→  for (const [userId, player] of Object.entries(players)) {
   282→    if (player.experience >= 0) {
   283→      // Calculer le niveau correct basé sur l'expérience totale
   284→      // Le système fonctionne comme suit :
   285→      // - Niveau 1 nécessite 100 XP pour passer au niveau 2
   286→      // - Niveau 2 nécessite 200 XP pour passer au niveau 3
   287→      // - Niveau 3 nécessite 300 XP pour passer au niveau 4, etc.
   288→
   289→      let totalExpUsed = 0;
   290→      let currentLevel = 1;
   291→      let totalExpAvailable = player.experience;
   292→
   293→      // Calculer le niveau en additionnant l'XP nécessaire pour chaque niveau
   294→      while (totalExpUsed + currentLevel * 100 <= totalExpAvailable) {
   295→        totalExpUsed += currentLevel * 100;
   296→        currentLevel++;
   297→      }
   298→
   299→      const remainingExp = totalExpAvailable - totalExpUsed;
   300→
   301→      // Vérifier si une correction est nécessaire
   302→      if (currentLevel !== player.level || remainingExp !== player.experience) {
   303→        console.log(
   304→          `Correction du joueur ${player.name}: Niveau ${player.level} -> ${currentLevel}, XP ${player.experience} -> ${remainingExp} (XP total: ${totalExpAvailable})`,
   305→        );
   306→
   307→        // Ajuster les stats si le niveau a augmenté
   308→        const oldLevel = player.level;
   309→        if (currentLevel > oldLevel) {
   310→          const levelDiff = currentLevel - oldLevel;
   311→          player.maxHealth += levelDiff * 10;
   312→          player.maxMana += levelDiff * 5;
   313→          player.stats.attack += levelDiff;
   314→          player.stats.defense += levelDiff;
   315→          player.stats.magicAttack += levelDiff;
   316→          player.stats.magicDefense += levelDiff;
   317→        }
   318→
   319→        player.level = currentLevel;
   320→        player.experience = remainingExp;
   321→        fixedCount++;
   322→      }
   323→    }
   324→  }
   325→
   326→  if (fixedCount > 0) {
   327→    savePlayersData(players);
   328→    console.log(`${fixedCount} joueurs corrigés pour l'expérience`);
   329→  }
   330→
   331→  return fixedCount;
   332→}
   333→
   334→/**
   335→ * Réinitialise complètement la base de données
   336→ */
   337→function resetDatabase() {
   338→  try {
   339→    savePlayersData({});
   340→    console.log("Base de données réinitialisée");
   341→    return true;
   342→  } catch (error) {
   343→    console.error("Erreur lors de la réinitialisation:", error);
   344→    return false;
   345→  }
   346→}
   347→
   348→/**
   349→ * Migre les anciennes données de quêtes vers la nouvelle structure
   350→ * Corrige les joueurs avec des quêtes actives invalides du ancien système
   351→ */
   352→function migrateQuestData() {
   353→  const players = loadPlayers();
   354→  let migratedCount = 0;
   355→  let abandonedCount = 0;
   356→
   357→  for (const [userId, player] of Object.entries(players)) {
   358→    // Vérifier si le joueur a une quête active
   359→    if (player.quests && player.quests.active) {
   360→      const quest = player.quests.active;
   361→
   362→      // Vérifier si c'est une ancienne quête sans les champs requis
   363→      // Une quête valide doit avoir un startTime
   364→      if (!quest.startTime) {
   365→        console.log(
   366→          `⚠️ Quête ancienne structure détectée pour ${player.name}: abandonnée automatiquement`,
   367→        );
   368→        player.quests.active = null;
   369→        abandonedCount++;
   370→        continue;
   371→      }
   372→
   373→      // Vérifier si startTime est valide
   374→      try {
   375→        const startTime = new Date(quest.startTime);
   376→        if (isNaN(startTime.getTime())) {
   377→          console.log(
   378→            `⚠️ Quête avec startTime invalide pour ${player.name}: abandonnée automatiquement`,
   379→          );
   380→          player.quests.active = null;
   381→          abandonedCount++;
   382→          continue;
   383→        }
   384→      } catch (e) {
   385→        console.log(
   386→          `⚠️ Erreur lors de la validation du startTime pour ${player.name}: quête abandonnée`,
   387→        );
   388→        player.quests.active = null;
   389→        abandonedCount++;
   390→        continue;
   391→      }
   392→
   393→      // Ajouter le champ progress s'il manque
   394→      if (!quest.hasOwnProperty("progress")) {
   395→        quest.progress = 0;
   396→        migratedCount++;
   397→      }
   398→    }
   399→
   400→    // S'assurer que la structure des quêtes est correcte
   401→    if (!player.quests) {
   402→      player.quests = {
   403→        active: null,
   404→        completed: [],
   405→        completedToday: 0,
   406→        lastQuestTime: null,
   407→      };
   408→    }
   409→  }
   410→
   411→  if (migratedCount > 0 || abandonedCount > 0) {
   412→    savePlayersData(players);
   413→    console.log(
   414→      `✅ Migration des quêtes terminée: ${migratedCount} quêtes migrées, ${abandonedCount} quêtes abandonnées`,
   415→    );
   416→  }
   417→
   418→  return { migratedCount, abandonedCount };
   419→}
   420→
   421→module.exports = {
   422→  loadPlayers,
   423→  savePlayersData,
